v AS (SELECT a.codigo, a.campo, a.esperado,
             CASE a.campo WHEN 'status' THEN t.status WHEN 'venda' THEN round(t.valor_venda)::text WHEN 'aluguel' THEN round(t.valor_aluguel)::text
                          WHEN 'financia' THEN t.financia WHEN 'condominio' THEN t.condominio END AS tela
        FROM alvo a LEFT JOIN vw_imoveis_todos t ON t.codigo = a.codigo)
SELECT count(*) AS conferidos, count(*) FILTER (WHERE tela IS NOT DISTINCT FROM esperado) AS iguais_ao_antigo FROM v;
